// JWT Token doğrulama
const crypto = require('crypto');

const authHeader = $input.item.json.headers.authorization;

if (!authHeader || !authHeader.startsWith('Bearer ')) {
  throw new Error('Token bulunamadı');
}

const token = authHeader.substring(7);
const secret = process.env.JWT_SECRET || 'CHANGE_THIS_SECRET_KEY_IN_PRODUCTION';

try {
  // Token'ı parse et
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Geçersiz token formatı');
  }

  const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());

  // Token süresini kontrol et
  if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) {
    throw new Error('Token süresi dolmuş');
  }

  // Token signature'ı doğrula
  const header = parts[0];
  const payloadStr = parts[1];
  const signature = parts[2];

  const expectedSignature = crypto.createHmac('sha256', secret)
    .update(`${header}.${payloadStr}`)
    .digest('base64');

  if (signature !== expectedSignature) {
    throw new Error('Geçersiz token signature');
  }

  return {
    json: {
      sube: payload.sube,
      authenticated: true,
      binary: $input.item.binary
    }
  };
} catch (error) {
  throw new Error('Token doğrulama hatası: ' + error.message);
}

// LLM çıktısını parse et ve temizle
let text = $json.message?.content || $json.output || $json.text || '';

// Markdown kod bloklarını temizle
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

// Parse JSON
let products;
try {
  products = JSON.parse(text);
} catch (e) {
  // Eğer parse edilemezse, JSON array olarak wrap et
  try {
    const singleProduct = JSON.parse(text);
    products = [singleProduct];
  } catch (e2) {
    console.error('JSON parse hatası:', text);
    throw new Error('Ürün bilgisi çıkarılamadı');
  }
}

// Array değilse array yap
if (!Array.isArray(products)) {
  products = [products];
}

// Şube ve timestamp bilgilerini ekle
const sube = $('JWT Verification').item.json.sube;
const timestamp = new Date();
const tarih = timestamp.toISOString().split('T')[0]; // YYYY-MM-DD

// Her ürün için ayrı item oluştur
return products.map(p => ({
  json: {
    urun: p.urun || p.product || '',
    miktar: parseFloat(p.miktar || p.quantity || 0),
    birim: p.birim || p.unit || 'ad',
    sube: sube,
    tarih: tarih,
    timestamp: timestamp.toISOString()
  }
}));

// Şubeye göre column mapping
const columnMap = {
  'merkez': 'B',
  'sube-kadikoy': 'C',
  'sube-besiktas': 'D',
  'sube-sisli': 'E',
  'sube-uskudar': 'F',
  'sube-bakirkoy': 'G'
};

const sube = $json.sube;
const column = columnMap[sube] || 'B';

return {
  json: {
    ...$json,
    column: column
  }
};

// Tüm sonuçları topla ve response formatla
const items = $input.all();

const products = items.map(item => ({
  urun: item.json.urun,
  miktar: item.json.miktar,
  birim: item.json.birim
}));

return {
  json: {
    success: true,
    message: `${products.length} ürün başarıyla kaydedildi`,
    products: products,
    timestamp: new Date().toISOString()
  }
};

// Error response formatter
const error = $input.item.error || $json.error || {};
const errorMessage = error.message || 'Bilinmeyen hata oluştu';

return {
  json: {
    success: false,
    error: errorMessage,
    timestamp: new Date().toISOString()
  }
};
